[Form]
public class FMStartRental extends FormRun
{
    FormDataSource rentalDS;
    FMVehicle vehicle; 
    FMRental rental; 

}

public void run()
{        
    super();    

    FMRental_StartDate.dateTimeValue(DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::utcNow(), DateTimeUtil::getUserPreferredTimeZone()));

    if(rental != null)
    {
        FMRental_EndDate.dateTimeValue(rental.EndDate);
        FMRental_StartMileage.value(rental.StartMileage);
    }

    if(vehicle != null)
    {
        FMVehicle_Description.text(vehicle.Description); 
    }    
}

public void init()
{
    //If this form was opened with a Rental as context then
    if(element.args() != null && element.args().record() != null)
    {
        //Grab that Rental context
        rentalDS = FormDataUtil::getFormDataSource(element.args().record());

        if(element.args().record().TableId == tableNum(FMPickupAndReturnTable))
        {
            FMPickupAndReturnTable cacheRecord = element.args().record();
            select firstonly forupdate rental where rental.RentalId == cacheRecord.RentalId;
        }
        else if(element.args().record().TableId == tableNum(FMRental))
        {
            rental = element.args().record();
        }

        if(rental != null)
        {
            select firstonly forupdate vehicle where vehicle.RecId == rental.Vehicle;
        }

    }

    super();       
}

public void clicked()
{

    Microsoft.Dynamics.Application.Instrumentation.FleetManagementEventSource::EventWriteXppTransactionStart("FleetManagement", "Start a rental");

    if(rental != null && vehicle != null)
    {
        if(FMRental_EndDate.dateTimeValue()  == DateTimeUtil::minValue())
        {
            warning("Need an end date");
            return;
        }

        Microsoft.Dynamics.Application.Instrumentation.FleetManagementEventSource::EventWriteXppTransactionStart("FleetManagement", "Release vehicle");

        ttsbegin;

        vehicle.Status = FMVehicleStatus::Rented;
        vehicle.Description = FMVehicle_Description.text();
        vehicle.update();

        rental.State = FMReservationState::InProgress;
        rental.StartDate = DateTimeUtil::removeTimeZoneOffset(FMRental_StartDate.dateTimeValue(), DateTimeUtil::getUserPreferredTimeZone());
        rental.EndDate = DateTimeUtil::removeTimeZoneOffset(FMRental_EndDate.dateTimeValue(), DateTimeUtil::getUserPreferredTimeZone());
        rental.StartMileage = FmRental_StartMileage.value();
        rental.update();

        ttscommit;

        Microsoft.Dynamics.Application.Instrumentation.FleetManagementEventSource::EventWriteXppTransactionStop("FleetManagement", "Release vehicle");
        info('Vehicle has been successfully released!');

        if(rentalDS.table() == tableNum(FMPickupAndReturnTable))
        {
            //Delete updated record from backing cache
            FMPickupAndReturnTable cacheRecord = element.args().record();
            cacheRecord.delete();
        }

        rentalDS.research(true);
    }

    super();

    Microsoft.Dynamics.Application.Instrumentation.FleetManagementEventSource::EventWriteXppTransactionStop("FleetManagement", "Start a rental");

}
